package com.torchat.core.card

import com.torchat.core.model.Endpoint
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * A card produced by the reference (Node) client, parsed here.
 *
 * ARCHITECTURE.md §15 asks for exactly this fixture and says not to proceed
 * without it: *"Do not proceed until a card generated by the desktop app
 * verifies here, and vice versa. Every later interop bug traces back to this
 * stage."* It was skipped, on the grounds that an Android-only MVP only ever
 * talks to itself — which stopped being true the moment a desktop client and a
 * phone were asked to talk to each other.
 *
 * The fixture in `node-card.txt` was generated by `src/core/card.js`.
 */
class InteropTest {

    private val nodeCard: String =
        checkNotNull(javaClass.getResourceAsStream("/node-card.txt")) {
            "node-card.txt fixture is missing"
        }.bufferedReader().readText().trim()

    @Test
    fun `a card from the reference client verifies`() {
        val parsed = Card.parse(nodeCard)

        assertTrue(parsed.id.startsWith("TOR-"))
        assertEquals("laptop", parsed.name)
        assertEquals("L", parsed.sigil)
    }

    @Test
    fun `its onion endpoint survives parsing`() {
        // The symptom this exists to catch: the engine rejects a perfectly good
        // card with "that code has no onion address" because the endpoints came
        // back empty or with an unusable host.
        val endpoints = Card.parse(nodeCard).endpoints

        assertEquals(1, endpoints.size)
        assertEquals("onion", endpoints.single().type)
        assertEquals(47777, endpoints.single().port)
        assertTrue(
            "host was '${endpoints.single().host}'",
            Endpoint.isOnion(endpoints.single().host),
        )
    }

    @Test
    fun `the endpoint survives the merge that guards the friend list`() {
        // Parsing is only half of it. Everything an address has to pass through
        // before it can be dialled is this merge (§9.1).
        val merged = Endpoint.mergeOnions(Card.parse(nodeCard).endpoints)

        assertEquals(1, merged.size)
        assertTrue(Endpoint.isDialable(merged.single()))
    }
}
